import { errorResult, okResult, type CliCommandResult } from '../envelope';
import { integerFlag } from '../flags';
import { requestServer } from '../client';
import { readRuntimeInterruptions } from '../runtimeInterruption';
import {
  attachOrUnavailable,
  isAttached,
  isCommandResult,
  parseCommandContext,
  serverErrorResult,
  transportErrorResult,
} from './shared';

const COMMAND = 'wait';
const DEFAULT_WAIT_TIMEOUT_SECONDS = 600;
const WAIT_POLL_INTERVAL_MS = 500;
const UNKNOWN_WORK_GRACE_MS = 10_000;

const WAIT_FLAG_SPEC = {
  timeout: { takesValue: true },
};

type StatusPayload = {
  queue?: {
    queued?: Array<{ requestId?: string }>;
    leases?: Array<{ requestId?: string; mergedRequestIds?: string[] }>;
  };
  activeRun?: { traceId?: string; agentRunId?: string } | null;
  settledRequestIds?: string[];
  variants?: {
    active?: boolean;
    variants?: Array<{
      requestId?: string;
      status?: string;
      refinement?: { status?: string };
    }>;
  };
};

type WorkState = 'settled' | 'pending' | 'running' | 'unknown';

const TERMINAL_VARIANT_STATUSES = new Set(['succeeded', 'failed', 'cancelled']);

export const workStateOf = (
  status: StatusPayload,
  workId: string,
): WorkState => {
  const activeRun = status.activeRun;
  if (
    activeRun &&
    (activeRun.agentRunId === workId || activeRun.traceId === workId)
  ) {
    return 'running';
  }
  const leases = status.queue?.leases ?? [];
  if (
    leases.some(
      (lease) =>
        lease.requestId === workId ||
        (lease.mergedRequestIds ?? []).includes(workId),
    )
  ) {
    return 'running';
  }
  const queued = status.queue?.queued ?? [];
  if (queued.some((item) => item.requestId === workId)) {
    return 'pending';
  }
  const correlatedVariants = (status.variants?.variants ?? []).filter(
    (variant) => variant.requestId === workId,
  );
  if (correlatedVariants.length > 0) {
    const isVariantWorkRunning = correlatedVariants.some((variant) => {
      const variantStatus = variant.refinement?.status ?? variant.status;
      return !variantStatus || !TERMINAL_VARIANT_STATUSES.has(variantStatus);
    });
    return isVariantWorkRunning ? 'running' : 'settled';
  }
  if ((status.settledRequestIds ?? []).includes(workId)) {
    return 'settled';
  }
  return 'unknown';
};

const waitTimeoutMessage = (
  workId: string,
  state: WorkState,
  timeoutSeconds: number,
): string =>
  state === 'pending'
    ? `Work ${workId} is still pending after ${timeoutSeconds}s. Check \`rivet status\`.`
    : `Work ${workId} is still running after ${timeoutSeconds}s. Re-issue \`rivet wait\` or check \`rivet status\`.`;

const unknownWorkMessage = (workId: string): string =>
  `Unknown work id ${workId}. Check \`rivet status\` for queued, running, or recently settled work.`;

const sleep = (ms: number): Promise<void> =>
  new Promise((resolve) => setTimeout(resolve, ms));

const interruptedWorkResult = ({
  projectPath,
  workId,
  isWorkUnknown = false,
}: {
  projectPath: string;
  workId: string;
  isWorkUnknown?: boolean;
}): CliCommandResult | null => {
  const receipts = readRuntimeInterruptions(projectPath);
  const confirmed = receipts.find((item) => item.workIds.includes(workId));
  const interruption =
    confirmed ??
    (isWorkUnknown
      ? receipts
          .filter((item) => item.workIds.length === 0)
          .sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0]
      : undefined);
  if (!interruption) return null;
  return errorResult(
    COMMAND,
    'OPERATION_FAILED',
    confirmed
      ? interruption.message
      : 'Rivet restarted after an upgrade without retaining work IDs. This work is unavailable, but its interruption cannot be confirmed. Run `rivet open`, check saved history, and restart the original request if needed.',
    {
      reason: 'runtime_upgraded',
      workId,
      interruption,
      isWorkConfirmedInterrupted: Boolean(confirmed),
    },
    { isRecoverable: true },
  );
};

export const handleWait = async (args: string[]): Promise<CliCommandResult> => {
  const context = parseCommandContext(COMMAND, args, WAIT_FLAG_SPEC);
  if (isCommandResult(context)) {
    return context;
  }
  const workId = context.flags.positionals[0];
  if (!workId) {
    return errorResult(
      COMMAND,
      'USAGE_ERROR',
      'Usage: rivet wait <workId> [--timeout <seconds>]',
    );
  }
  const timeoutSeconds =
    integerFlag(context.flags, 'timeout') ?? DEFAULT_WAIT_TIMEOUT_SECONDS;
  if (context.flags.errors.length > 0) {
    return errorResult(COMMAND, 'USAGE_ERROR', context.flags.errors.join('; '));
  }

  const recovery = { projectPath: context.projectPath, workId };
  const interrupted = interruptedWorkResult(recovery);
  if (interrupted) return interrupted;
  const attached = await attachOrUnavailable(COMMAND, context.projectPath);
  if (!isAttached(attached)) {
    return (
      interruptedWorkResult({ ...recovery, isWorkUnknown: true }) ?? attached
    );
  }

  const deadline = Date.now() + timeoutSeconds * 1000;
  const unknownGraceDeadline = Date.now() + UNKNOWN_WORK_GRACE_MS;
  let wasObservedRunning = false;
  let wasObservedLive = false;
  for (;;) {
    const interruption = interruptedWorkResult(recovery);
    if (interruption) return interruption;
    let status: StatusPayload;
    try {
      const response = await requestServer<StatusPayload>(
        attached,
        '/api/cli/status',
      );
      if (response.status !== 200) {
        return serverErrorResult(COMMAND, response.status, response.body);
      }
      status = response.body;
    } catch (error) {
      return (
        interruptedWorkResult(recovery) ?? transportErrorResult(COMMAND, error)
      );
    }

    const workState = workStateOf(status, workId);
    if (workState === 'settled') {
      return okResult(COMMAND, {
        workId,
        state: 'settled',
        wasObservedRunning,
      });
    }
    if (workState === 'unknown') {
      if (wasObservedLive) {
        return okResult(COMMAND, {
          workId,
          state: 'settled',
          wasObservedRunning,
        });
      }
      if (Date.now() >= unknownGraceDeadline || Date.now() >= deadline) {
        const recoveryResult = interruptedWorkResult({
          ...recovery,
          isWorkUnknown: true,
        });
        if (recoveryResult) return recoveryResult;
        return errorResult(
          COMMAND,
          'OPERATION_FAILED',
          unknownWorkMessage(workId),
          {
            workId,
            state: 'unknown',
          },
        );
      }
    }
    if (workState === 'running') {
      wasObservedRunning = true;
    }
    if (workState === 'running' || workState === 'pending') {
      wasObservedLive = true;
    }

    if (Date.now() >= deadline) {
      return errorResult(
        COMMAND,
        'WAIT_TIMEOUT',
        waitTimeoutMessage(workId, workState, timeoutSeconds),
        { workId, state: workState },
      );
    }
    await sleep(WAIT_POLL_INTERVAL_MS);
  }
};
